    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openStockDutyWin
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo prtdepoId listProcsStatCd
 * @returns
 * @hidden N
*/
scwin.openStockDutyWin = async function (bzProcsNo, prtdepoId, listProcsStatCd) {
