/**
 * @method
 * @name scwin.checkDate
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.checkDate = function (val) {
    /* sdd-asis-lifecycle:begin checkDate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (val.length == 0) {
        return true;
    }
    if (val.length != 8) {
        return false;
    }
    const year = val.substring(0, 4);
    const month = val.substring(4, 6);
    const day = val.substring(6, 8);
    if (month > 12 || month < 1) {
        return false;
    }
    if (month == 2 || month == 02) {
        if (day > 29 || day < 1) {
            return false;
        }
    } else {
        if (month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) {
            if (day > 31 || day < 1) {
                return false;
            }
        } else {
            if (month == 4 || month == 6 || month == 9 || month == 11) {
                if (day > 30 || day < 1) {
                    return false;
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.stockDutySubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo prtdepoId updateType cnt
 * @returns
 * @hidden N
*/
scwin.stockDutySubmit = async function (bzProcsNo, prtdepoId, updateType, cnt) {
    /* sdd-asis-lifecycle:begin fn_stockDutySubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.stockDutySubForm || { elements: [] });
    if (!scwin.checkDate(scwin.stockDutyarr[cnt].prtdepoEndDd) || !scwin.checkDate(scwin.stockDutyarr[cnt].stkoptDutyExerEndDd) || !scwin.checkDate(scwin.stockDutyarr[cnt].stkoptDutyExerStartDd) || !scwin.checkDate(scwin.stockDutyarr[cnt].stkoptDutyResolDd)) {
        await $c.win.alert("날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.");
        return;
    }
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_openStockDutyWinReq').set('bzProcsNo', bzProcsNo);
        $c.util.getComponent('dma_openStockDutyWinReq').set('prtdepoId', prtdepoId);
        $c.util.getComponent('dma_openStockDutyWinReq').set('listProcsStatCd', updateType);
        scwin.form.action = '/list/listDisclosureForm.do';
        $c.util.getComponent("dma_openStockDutyWinReq").set("method", 'stockDutySubmit');
        await scwin.tx_fn_stockDutySubmit();
    }
    /* sdd-asis-lifecycle:end */
};


